<?php
require dirname(__DIR__).'/dashboard/private/state.php';
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$s=initial_state();$j=add_job($s,['docket'=>'25-735','argument_date'=>'2026-10-05','audio_url'=>'https://www.supremecourt.gov/a.mp3','pdf_url'=>'https://www.supremecourt.gov/t.pdf']);$id=$j['id'];command($s,['command'=>'start','job'=>$id]);
$d=worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'prepare'],'dispatcher');$base=['job'=>$id,'stage'=>'prepare','dispatch_token'=>$d['dispatch_token']];$c=worker_update($s,['op'=>'claim',...$base],'prepare');
$f=['op'=>'finish',...$base,'lease'=>$c['lease'],'result'=>['transcript_uri'=>'gs://bucket/prepared.json','duration_seconds'=>6100],'continue_enrich'=>true,'handoff_id'=>str_repeat('a',32)];$next=worker_update($s,$f,'prepare');check($next['next']['stage']==='enrich','Preparation did not reserve enrichment');check(worker_update($s,$f,'prepare')['next']['dispatch_token']===$next['next']['dispatch_token'],'Lost reply changed enrichment identity');
$en=['job'=>$id,'stage'=>'enrich','dispatch_token'=>$next['next']['dispatch_token']];$ec=worker_update($s,['op'=>'claim',...$en],'enrich');
$ad=worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'align'],'dispatcher');check(!empty($ad),'Enrichment blocked alignment');$al=['job'=>$id,'stage'=>'align','dispatch_token'=>$ad['dispatch_token']];$ac=worker_update($s,['op'=>'claim',...$al],'align');check(worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'plan'],'dispatcher')===null,'Planning bypassed parallel branches');
$working=$s;worker_update($working,['op'=>'fail',...$al,'lease'=>$ac['lease'],'error'=>'worker_failed'],'align');$rid=$working['jobs'][$id]['stages']['align']['recovery_id'];check(recovery_operation($working,['op'=>'recovery_dispatch','recovery'=>$rid,'reserve_usd'=>0.1,'seconds'=>600],'dispatcher')===null,'Recovery competed with the healthy Codex enrichment branch');
$held=$s;worker_update($held,['op'=>'fail',...$al,'lease'=>$ac['lease'],'error'=>'worker_failed'],'align');worker_update($held,['op'=>'enrichment_review',...$en,'lease'=>$ec['lease'],'review'=>['id'=>'review','revision'=>str_repeat('b',64),'titles'=>[],'photos'=>['lawyer'=>['name'=>'Lawyer','candidates'=>[]]]],'result'=>[]],'enrich');check($held['jobs'][$id]['status']==='failed','Photo hold concealed failed alignment');command($held,['command'=>'retry','job'=>$id]);check($held['jobs'][$id]['stages']['enrich']['status']==='needs_review','Alignment retry invalidated existing photo review');
$failed=$s;worker_update($failed,['op'=>'fail',...$en,'lease'=>$ec['lease'],'error'=>'worker_failed'],'enrich');$saved=$failed['jobs'][$id]['stages']['align'];command($failed,['command'=>'retry','job'=>$id]);check($failed['jobs'][$id]['stages']['align']===$saved,'Enrichment retry invalidated active alignment');check(worker_update($failed,['op'=>'dispatch','job'=>$id,'stage'=>'enrich'],'dispatcher')!==null,'Failed branch could not retry alongside alignment');
worker_update($s,['op'=>'finish',...$al,'lease'=>$ac['lease'],'result'=>['transcript_uri'=>'gs://bucket/aligned.json']],'align');check(worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'plan'],'dispatcher')===null,'Finished alignment bypassed enrichment');worker_update($s,['op'=>'finish',...$en,'lease'=>$ec['lease'],'result'=>[]],'enrich');check(worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'plan'],'dispatcher')!==null,'Joined branches did not enable planning');
echo "Research handoff checks passed: checkpoint, concurrent branches, join and independent retry.\n";
